onCreate.script:
// === Effect Macro Echo + Owner Probe (for Effect Macro module) v2.0 ========
// Uses the module-provided helpers: effect, actor, token, scene, origin, speaker, item
// Fire this on any of:
//   - On Effect Creation / On Effect Deletion
//   - On Combat Turn Starting / Ending
//   - On Combat Round Starting / Ending
//   - (and others if you like: On Each Combat Turn, On Combat Starting/Ending, etc.)
// What it does:
//   • Prints a chat line confirming the trigger fired
//   • Shows Effect name/uuid, Owner Actor, Token (if any), Scene, Origin
//   • Proves owner access by writing a harmless timestamp flag on the owner
//   • Logs full context to console for deeper debugging
// ============================================================================
(async () => {
  // --- Sanity: the module should have given us these -----------------------
  // effect: ActiveEffect
  // actor:  Owner actor (or null)
  // token:  First active token for actor on current scene (or null)
  // scene:  Scene of the token or active scene
  // origin: Document pointed by effect.origin (or null)
  // speaker: Pre-built speaker for chat (speaks as the actor if present)
  // item:   Item the effect is on (if not on actor directly), else null

  const effectName = effect?.name ?? "(unnamed effect)";
  const effectUuid = effect?.uuid ?? "(no uuid)";
  const ownerName  = actor?.name ?? "(no owner found)";
  const tokenName  = token?.name ?? "(no active token)";
  const sceneName  = scene?.name ?? "(no scene)";
  const originStr  = origin ? `${origin.documentName ?? origin.type ?? "Doc"} — ${origin.uuid ?? ""}` : "(none)";

  const combat = game.combat;
  const round  = combat?.round ?? "-";
  const turn   = combat ? (combat.turn + 1) : "-";

  const lines = [
    `<b>[Effect Macro]</b> fired.`,
    `• <b>Effect</b>: ${effectName}`,
    `• <b>Effect UUID</b>: ${effectUuid}`,
    `• <b>Owner Actor</b>: ${ownerName}`,
    `• <b>Owner Token</b>: ${tokenName}`,
    item   ? `• <b>Item</b>: ${item.name}` : null,
    `• <b>Origin</b>: ${originStr}`,
    `• <b>Scene</b>: ${sceneName}`,
    `• <b>Combat</b>: Round ${round}, Turn ${turn}`
  ].filter(Boolean);

  await ChatMessage.create({
    speaker,
    content: `<div style="font-family:Signika, sans-serif; line-height:1.25">
      ${lines.map(l => `<div>${l}</div>`).join("")}
    </div>`
  });

  // --- Non-destructive proof we can access/modify the owner ----------------
  // Store a "last fired" timestamp under a namespaced flag on the owner actor.
  if (actor) {
    const ns = "oni.effectmacro-demo";
    const key = "lastFired";
    const prev = (await actor.getFlag(ns, key)) ?? {};
    prev[effect.id] = Date.now();
    await actor.setFlag(ns, key, prev);
  }

  // Extra diagnostics in DevTools console (F12)
  console.debug("[Effect Macro Echo] context:", { effect, actor, token, scene, origin, speaker, item, combat: game.combat });
})();

